begin;
select no_plan();
select set_config('request.jwt.claim.role','service_role',true);
delete from private.ecosystem_notifications;
delete from public.member_notifications;
delete from public.member_notification_events;
delete from private.synthetic_notification_resolutions;
select ok(private.notification_reserved_recipient(email),'reserved: '||email) from (values ('x@example.test'),('x@sub.example'),('x@EXAMPLE.COM'),('x@sub.example.org'),('x@example.net.'),('x@localhost'),('x@foo.invalid')) t(email);
select ok(not private.notification_reserved_recipient(email),'not reserved: '||email) from (values ('x@myexample.com'),('x@example.com.other'),('x@armatureailabs.com')) t(email);
select ok(not has_function_privilege('authenticated','public.skip_reserved_member_notification(uuid,uuid)','EXECUTE'),'browser cannot skip');
select ok(not has_function_privilege('service_role','private.resolve_synthetic_notification(text,text,text,text,text)','EXECUTE'),'worker cannot classify synthetic receipts');
select ok(not has_table_privilege('authenticated','private.synthetic_notification_resolutions','SELECT,INSERT,UPDATE,DELETE'),'evidence private');
insert into auth.users(id,aud,role,email,email_confirmed_at) values('b7900000-0000-4000-8000-000000000099','authenticated','authenticated','synthetic@example.test',now());
insert into public.member_notifications(id,user_id,recipient_id,recipient_email,event_key,kind,expected_status,application_revision,state,lease_token,lease_until,first_attempt_at)
select ('b7600000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b7900000-0000-4000-8000-000000000099','b7900000-0000-4000-8000-000000000099',case when n=4 then 'person@armatureailabs.com' else 'synthetic@example.test' end,'reserved-'||n,'approved','approved',1,case when n=3 then 'sending' else 'leased' end,'b7200000-0000-4000-8000-000000000099',now()+interval '5 minutes',case when n=2 then now() else null end from generate_series(1,4)n;
select ok(public.skip_reserved_member_notification('b7600000-0000-4000-8000-000000000001','b7200000-0000-4000-8000-000000000099'),'fresh reserved lease skipped');
select is((select state from public.member_notifications where event_key='reserved-1'),'suppressed','never-attempted synthetic is suppressed');
select ok(public.skip_reserved_member_notification('b7600000-0000-4000-8000-000000000002','b7200000-0000-4000-8000-000000000099'),'prior attempted reserved lease blocks another send');
select is((select state from public.member_notifications where event_key='reserved-2'),'unknown','prior attempt stays actionable');
select ok(not public.skip_reserved_member_notification('b7600000-0000-4000-8000-000000000003','b7200000-0000-4000-8000-000000000099'),'sending state untouched');
select ok(not public.skip_reserved_member_notification('b7600000-0000-4000-8000-000000000004','b7200000-0000-4000-8000-000000000099'),'real destination untouched');
select public.record_member_notification_event('synthetic-unmatched','b7300000-0000-4000-8000-000000000099','email.bounced',now());
select public.record_member_notification_event('real-unmatched','b7300000-0000-4000-8000-000000000098','email.failed',now());
update public.member_notification_events set received_at=now()-interval '2 hours';
select is((public.notification_delivery_health()->>'unmatched_receipts')::integer,2,'unclassified reports actionable');
select throws_ok($$select private.resolve_synthetic_notification('b7300000-0000-4000-8000-000000000098','person@armatureailabs.com','Subject','Exact provider evidence verified by operator for synthetic test','test operator')$$,'22023','Reserved recipient and unmatched provider evidence required','real domain cannot be resolved synthetic');
select private.resolve_synthetic_notification('b7300000-0000-4000-8000-000000000099','synthetic@example.test','Subject','Exact provider evidence verified by operator for synthetic test','test operator');
select is((public.notification_delivery_health()->>'unmatched_receipts')::integer,1,'only exact resolved synthetic provider excluded');
select is((select count(*)::integer from public.member_notification_events),2,'raw negative receipts preserved');
select is((public.notification_delivery_health()->>'unknown')::integer,1,'ambiguous earlier send still alerts');
select is((select count(*)::integer from jsonb_object_keys(public.notification_delivery_health())),18,'monitor schema unchanged');
select * from finish();
rollback;
